// LeetCode 0210 - Course Schedule II
func findOrder(numCourses int, prerequisites [][]int) []int { graph := make([][]int, numCourses); indegree := make([]int, numCourses); for _, edge := range prerequisites { course, pre := edge[0], edge[1]; graph[pre] = append(graph[pre], course); indegree[course]++ }; queue := make([]int, 0, numCourses); for course := 0; course < numCourses; course++ { if indegree[course] == 0 { queue = append(queue, course) } }; order := make([]int, 0, numCourses); for len(queue) > 0 { course := queue[0]; queue = queue[1:]; order = append(order, course); for _, next := range graph[course] { indegree[next]--; if indegree[next] == 0 { queue = append(queue, next) } } }; if len(order) != numCourses { return []int{} }; return order }
